input.new_string:
private string GetSignatureImageHtml()
{
    string[] arrPaths = new string[] {
        Application.StartupPath + "\\MauHtml\\mau-chu-ky.png",
        Application.StartupPath + "\\..\\..\\MauHtml\\mau-chu-ky.png",
        Application.StartupPath + "\\..\\..\\..\\MauHtml\\mau-chu-ky.png"
    };

    for (int i = 0; i < arrPaths.Length; i++)
    {
        try
        {
            string strFull = System.IO.Path.GetFullPath(arrPaths[i]);
            if (!System.IO.File.Exists(strFull))
                continue;

            byte[] arrBytes = System.IO.File.ReadAllBytes(strFull);
            string strBase64 = Convert.ToBase64String(arrBytes);
            return "<img class='sign-img' alt='' src='data:image/png;base64," + strBase64 + "' />";
        }
        catch
        {
        }
    }

    return "";
}

private string BuildSignatureHtml(DataRow drwInfo)
{
    string strDecisionNo = GetDataRowText(drwInfo, "DecisionNo");
    string strSigningDate = FormatSigningDate(drwInfo.Table.Columns.Contains("Signingdate") ? drwInfo["Signingdate"] : null);

    string strHieuTruong = SystemService.SYS_SettingService.GetStringValue("HIEUTRUONG");
    if (strHieuTruong == null)
        strHieuTruong = "";

    string strSignImg = GetSignatureImageHtml();

    StringBuilder sb = new StringBuilder();
    sb.Append("<div class='decision-line-sign'>- Quyết định công nhận tốt nghiệp số ")
        .Append(HtmlEncodeText(strDecisionNo))
        .Append(", ngày ")
        .Append(HtmlEncodeText(strSigningDate))
        .Append("</div>");

    sb.Append("<table class='footer-table'><tr>");
    sb.Append("<td style='width:40%'></td>");
    sb.Append("<td style='width:60%' class='footer-sign'>");
    sb.Append("<div class='sign-title'>HIỆU TRƯỞNG</div>");
    if (strSignImg.Length > 0)
        sb.Append("<div class='sign-image-wrap'>").Append(strSignImg).Append("</div>");
    if (strHieuTruong.Length > 0)
    {
        if (strSignImg.Length > 0)
            sb.Append("<div class='sign-name'>").Append(HtmlEncodeText(strHieuTruong)).Append("</div>");
        else
            sb.Append("<div class='sign-name sign-name-space'>").Append(HtmlEncodeText(strHieuTruong)).Append("</div>");
    }
    else if (strSignImg.Length < 1)
    {
        sb.Append("<div class='sign-name sign-name-space'>&nbsp;</div>");
    }
    sb.Append("</td>");
    sb.Append("</tr></table>");
    return sb.ToString();
}

